<?php /** @var array $r @var array $attachments @var array $events */ ?>
<div class="page-head"><div><h1><?= icon('book') ?> <?= e($r['code']) ?> — <?= e($r['title']) ?></h1><p class="sub"><span class="badge <?= $r['status'] === 'active' ? 'ok' : '' ?>"><?= e(t('enum.rstatus.' . $r['status'])) ?></span> <span class="badge islamic"><?= e(t('enum.rtype.' . $r['ruling_type'])) ?></span></p></div>
  <div class="actions"><a class="btn secondary" href="<?= e(url('sharia/rulings')) ?>"><?= e(t('common.back')) ?></a><?php if (can('sharia.manage')): ?><a class="btn" href="<?= e(url('sharia/rulings/' . $r['id'] . '/edit')) ?>"><?= e(t('common.edit')) ?></a><?php endif; ?></div></div>
<section class="card"><dl class="details"><dt><?= e(t('sha.r_subject')) ?></dt><dd><?= e($r['subject']) ?></dd><dt><?= e(t('sha.r_issued')) ?></dt><dd><?= e(fdate($r['issued_on'])) ?></dd><dt><?= e(t('sha.r_ref')) ?></dt><dd><?= e($r['reference_no'] ?? '—') ?></dd>
<dt><?= e(t('sha.r_text')) ?></dt><dd class="pre"><?= e($r['ruling_text']) ?></dd></dl></section>
<?php if ($events): ?><section class="card"><h2><?= e(t('sha.related_events')) ?></h2><ul class="task-list"><?php foreach ($events as $e): ?><li><a href="<?= e(url('sharia/events/' . $e['id'])) ?>"><?= e($e['code']) ?> — <?= e($e['title']) ?></a><span class="badge"><?= e(t('enum.sevent.' . $e['status'])) ?></span></li><?php endforeach; ?></ul></section><?php endif; ?>
<section class="card" id="attachments"><h2><?= e(t('upload.title')) ?></h2>
<?php if (!$attachments): ?><p class="muted"><?= e(t('upload.empty')) ?></p><?php else: ?><ul><?php foreach ($attachments as $a): ?><li><a href="<?= e(url('attachments/' . $a['id'])) ?>"><?= e($a['original_name']) ?></a>
<?php if (can('sharia.manage')): ?><form method="post" class="inline" action="<?= e(url('attachments/' . $a['id'] . '/delete')) ?>" data-confirm="<?= e(t('upload.confirm_delete')) ?>"><?= csrf_field() ?><button class="btn small danger" type="submit"><?= e(t('common.delete')) ?></button></form><?php endif; ?></li><?php endforeach; ?></ul><?php endif; ?>
<?php if (can('sharia.manage')): ?><form method="post" enctype="multipart/form-data" action="<?= e(url('sharia/rulings/' . $r['id'] . '/attachments')) ?>"><?= csrf_field() ?><div class="field"><label for="file"><?= e(t('upload.choose')) ?></label><input type="file" id="file" name="file" required></div><button class="btn secondary" type="submit"><?= e(t('upload.submit')) ?></button></form><?php endif; ?></section>
